    // ════════════════════════════════════════
    // LIFECYCLE
    // ════════════════════════════════════════
    protected override async Task OnInitializedAsync()
    {
        try
        {
            Logger.LogInformation("TopNavbar initializing...");

            // Bước 1: Lấy session và tab ID (cần trước khi làm gì khác)
            await RegisterStorageListener();
            sharedTabId = await GetSharedTabId();
            await LoadUserSession();

            // Bước 2: ✅ Load school info và nam hoc SONG SONG (Task.WhenAll)
            // Hai tác vụ này hoàn toàn độc lập → giảm thời gian từ T1+T2 xuống còn max(T1,T2)
            await Task.WhenAll(
                LoadSchoolInfo(),
                LoadNamHocList()
            );

            // Bước 3: Load các storage values (phụ thuộc vào kết quả bước 2)
            await Task.WhenAll(
                LoadSelectedLevelFromStorage(),
                LoadSelectedNamHocFromStorage()
            );

            // Bước 4: Fallback nam hoc nếu chưa có
            if (string.IsNullOrEmpty(selectedNamHoc) && namHocList.Any())
            {
                var first = namHocList.FirstOrDefault();
                if (first != null)
                {
                    selectedNamHoc = first.MaNamHoc;
                    selectedTenNamHoc = first.TenNamHoc;
                }
            }

            // Bước 5: Load hoc ky (phụ thuộc vào selectedNamHoc)
            if (!string.IsNullOrEmpty(selectedNamHoc))
                await LoadHocKyList(selectedNamHoc);

            await LoadSelectedHocKyFromStorage();

            if (!selectedHocKy.HasValue && hocKyList.Any())
                await DetermineAndSaveDefaultHocKy();

            BuildMenu();
            InitializeTimers();
            NavManager.LocationChanged += HandleLocationChanged;

            Logger.LogInformation("TopNavbar initialized successfully");
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error initializing TopNavbar");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();

            // ── ẨN LOADING OVERLAY ──────────────────────────────────────────
            // Gọi sau khi Blazor render xong (StateHasChanged) → người dùng thấy
            // nội dung đầy đủ rồi mới mất spinner (delay 150ms để transition mượt)
            try
            {
                await JS.InvokeVoidAsync("hideAppLoading", 150);
            }
            catch
            {
                // Bỏ qua nếu JS chưa sẵn sàng — fallback 6s trong _Host.cshtml sẽ xử lý
            }
        }
    }

