    private void BuildMenu()
    {
        MenuItems = new List<MenuItem>();

        MenuItems.Add(new MenuItem { Title = "Tổng quan", Link = "dashboard", Icon = "dashboard", IconColor = "#facc15" });
        MenuItems.Add(new MenuItem { Title = "Chức năng", Link = "quanlytruonghoc", Icon = "apps", IconColor = "#facc15" });
        MenuItems.Add(new MenuItem { Title = "Quản lý điểm", Link = "quanlydiemso", Icon = "apps", IconColor = "#facc15" });
        MenuItems.Add(new MenuItem { Title = "Hoạt động hằng ngày", Link = "hoat-dong-hang-ngay", Icon = "fitbit", IconColor = "#facc15" });
        MenuItems.Add(new MenuItem { Title = "Thống kê số liệu", Link = "analytic", Icon = "analytics", IconColor = "#facc15" });
    }

