    // STORAGE & SESSION
    // ════════════════════════════════════════
    private async Task RegisterStorageListener()
    {
        try
        {
            var dotNetRef = DotNetObjectReference.Create(this);
            await JS.InvokeVoidAsync("eval", @"
                window.sessionHelper = window.sessionHelper || {};
                window.sessionHelper.storageListener = function(dotNetRef) {
                    window.addEventListener('storage', function(e) {
                        if (e.key && (e.key.startsWith('UserSession_') || e.key === 'SharedTabId'
                            || e.key === 'selectedNamHoc' || e.key === 'selectedHocKy')) {
                            dotNetRef.invokeMethodAsync('OnStorageChanged', e.key);
                        }
                    });
                };
            ");
            await JS.InvokeVoidAsync("window.sessionHelper.storageListener", dotNetRef);
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error registering storage listener");
        }
    }

    [JSInvokable]
    public async Task OnStorageChanged(string key)
    {
        try
        {
            if (key.StartsWith("UserSession_") || key == "SharedTabId")
            {
                await LoadUserSession();
                await InvokeAsync(StateHasChanged);
            }
            else if (key == "selectedNamHoc" || key == "selectedHocKy")
            {
                NavManager.NavigateTo(NavManager.Uri, true);
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error handling storage change");
        }
    }

    private async Task<string> GetSharedTabId()
    {
        try
        {
            var tabId = await JS.InvokeAsync<string>("localStorage.getItem", "SharedTabId");
            if (string.IsNullOrEmpty(tabId))
            {
                tabId = $"tab_{DateTime.UtcNow.Ticks}_{Guid.NewGuid():N}";
                await JS.InvokeVoidAsync("localStorage.setItem", "SharedTabId", tabId);
            }
            return tabId;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error getting SharedTabId");
            return $"tab_fallback_{DateTime.UtcNow.Ticks}";
        }
    }

    private async Task LoadUserSession()
    {
        try
        {
            currentUser = UserState.CurrentUser;
            if (currentUser == null)
                currentUser = await BrowserStorageService.GetUserSessionAsync(JS);

            if (currentUser != null)
            {
                currentUserRole = string.IsNullOrWhiteSpace(currentUser.Role)
                    ? "Người dùng"
                    : currentUser.Role;
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading user session");
        }
    }

    private async Task LoadSchoolInfo()
    {
        try
        {
            if (currentUser != null && !string.IsNullOrEmpty(currentUser.MaTruongBo))
            {
                thongTinTruong = await TruongService.hThongTinTruongByID(currentUser.MaTruongBo);

                if (thongTinTruong?.Cap != null)
                {
                    availableLevels = thongTinTruong.Cap
                        .Where(cap => cap != "")
                        .Select(cap => new LevelOption
                            {
                                Value = cap,
                                Text = GetLevelDisplayName(cap)
                            })
                        .ToList();
                }
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading school info");
        }
    }

    // DATA LOADING
    // ════════════════════════════════════════
    private async Task LoadNamHocList()
    {
        try
        {
            namHocList = await TruongService.hGetCauHinhNamHoc(currentUser.MaTruongBo);
            namHocList = namHocList.OrderBy(x => x.NgayBatDau).ToList();

            DateTime today = DateTime.Today;
            CauHinhNamHocDTO? selected =
                namHocList.FirstOrDefault(x => x.NgayBatDau.HasValue && x.NgayKetThuc.HasValue
                    && today >= x.NgayBatDau.Value.Date && today <= x.NgayKetThuc.Value.Date)
                ?? namHocList.FirstOrDefault(x => x.NgayBatDau.HasValue && x.NgayBatDau.Value.Date > today)
                ?? namHocList.OrderByDescending(x => x.NgayBatDau).FirstOrDefault();

            if (selected != null)
            {
                selectedNamHoc = selected.MaNamHoc;
                selectedTenNamHoc = selected.TenNamHoc;
                await BrowserStorageService.SetItem(JS, "selectedNamHoc", selectedNamHoc);
                await BrowserStorageService.SetItem(JS, "selectedNamHocText", selectedTenNamHoc);
            }
            else if (namHocList.Any())
            {
                selectedNamHoc = namHocList[0].MaNamHoc;
                selectedTenNamHoc = namHocList[0].TenNamHoc;
                await BrowserStorageService.SetItem(JS, "selectedNamHoc", selectedNamHoc);
                await BrowserStorageService.SetItem(JS, "selectedNamHocText", selectedTenNamHoc);
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading nam hoc list");
        }
    }

    private async Task LoadHocKyList(string namHoc)
    {
        if (string.IsNullOrEmpty(namHoc)) { hocKyList.Clear(); return; }
        try
        {
            hocKyList = (await TruongService.hGetDanhSachHocKy(namHoc))
                .OrderBy(x => x.HocKy).ToList();
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading hoc ky list");
        }
    }

    private async Task DetermineAndSaveDefaultHocKy()
    {
        if (!hocKyList.Any()) return;
        DateTime now = DateTime.Now;
        var selected = hocKyList.FirstOrDefault(x =>
            x.ThoiGianBatDau.HasValue && x.ThoiGianKetThuc.HasValue
            && now >= x.ThoiGianBatDau.Value && now <= x.ThoiGianKetThuc.Value)
            ?? hocKyList[0];

        selectedHocKy = selected.HocKy;
        selectedTenHocKy = selected.TenHocKy;
        await BrowserStorageService.SetItem(JS, "selectedHocKy", selectedHocKy.ToString());
        await BrowserStorageService.SetItem(JS, "selectedHocKyText", selectedTenHocKy);
    }

    private async Task LoadSelectedNamHocFromStorage()
    {
        try
        {
            var saved = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
            var savedText = await BrowserStorageService.GetItem(JS, "selectedNamHocText");
            if (!string.IsNullOrEmpty(saved) && namHocList.Any(x => x.MaNamHoc == saved))
            {
                selectedNamHoc = saved;
                selectedTenNamHoc = savedText ?? namHocList.First(x => x.MaNamHoc == saved).TenNamHoc;
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading selected nam hoc from storage");
        }
    }

    private async Task LoadSelectedHocKyFromStorage()
    {
        try
        {
            var saved = await BrowserStorageService.GetItem(JS, "selectedHocKy");
            var savedText = await BrowserStorageService.GetItem(JS, "selectedHocKyText");
            if (!string.IsNullOrEmpty(saved) && int.TryParse(saved, out int hk) && hocKyList.Any(x => x.HocKy == hk))
            {
                selectedHocKy = hk;
                selectedTenHocKy = savedText ?? hocKyList.First(x => x.HocKy == hk).TenHocKy;
            }
            else
            {
                selectedHocKy = null;
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading selected hoc ky from storage");
            selectedHocKy = null;
        }
    }
    private async Task LoadSelectedLevelFromStorage()
    {
        try
        {
            var saved = await BrowserStorageService.GetItem(JS, "selectedLevel");
            var savedText = await BrowserStorageService.GetItem(JS, "selectedLevelText");

            // nếu có storage -> dùng storage
            if (!string.IsNullOrEmpty(saved)
                && availableLevels.Any(x => x.Value == saved))
            {
                selectedLevelValue = saved;
                currentLevel = savedText
                    ?? availableLevels.First(x => x.Value == saved).Text;
            }
            // nếu chưa có -> lấy level đầu tiên
            else if (availableLevels.Any())
            {
                var first = availableLevels.First();

                selectedLevelValue = first.Value;
                currentLevel = first.Text;

                await BrowserStorageService.SetItem(JS, "selectedLevel", first.Value);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", first.Text);
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading selected level");
        }
    }

    // ════════════════════════════════════════
    // SELECT ACTIONS
    // ════════════════════════════════════════
    private async Task SelectLevel(string value, string text)
    {
        await BrowserStorageService.SetItem(JS, "selectedLevel", value);
        await BrowserStorageService.SetItem(JS, "selectedLevelText", text);
        selectedLevelValue = value;
        currentLevel = text;
        CloseAllDropdowns();
        BuildMenu();
        NavManager.NavigateTo("/dashboard", true);
    }

    private async Task SelectNamHoc(string maNamHoc, string tenNamHoc)
    {
        if (selectedNamHoc == maNamHoc) return;
        selectedNamHoc = maNamHoc;
        selectedTenNamHoc = tenNamHoc;
        await BrowserStorageService.SetItem(JS, "selectedNamHoc", maNamHoc);
        await BrowserStorageService.SetItem(JS, "selectedNamHocText", tenNamHoc);
        await LoadHocKyList(maNamHoc);
        await DetermineAndSaveDefaultHocKy();
        CloseAllDropdowns();
        NavManager.NavigateTo(NavManager.Uri, true);
    }

    private async Task SelectHocKy(int hocKy, string tenHocKy)
    {
        bool changed = selectedHocKy != hocKy;
        selectedHocKy = hocKy;
        selectedTenHocKy = tenHocKy;
        await BrowserStorageService.SetItem(JS, "selectedHocKy", hocKy.ToString());
        await BrowserStorageService.SetItem(JS, "selectedHocKyText", tenHocKy);
        CloseAllDropdowns();
        if (changed) NavManager.NavigateTo(NavManager.Uri, true);
        else StateHasChanged();
    }

    // ════════════════════════════════════════
    // TIMER / SESSION
    // ════════════════════════════════════════
    private void InitializeTimers()
    {
        var uiTimer = new System.Timers.Timer(1000);
        uiTimer.Elapsed += async (s, e) => await UpdateRemainingTime();
        uiTimer.AutoReset = true;
        uiTimer.Enabled = true;
    }

    private async Task UpdateRemainingTime()
    {
        var currentUser = UserState.CurrentUser;
        if (currentUser == null || currentUser.ExpiryTime == DateTime.MinValue) return;

        var expiry = currentUser.ExpiryTime.ToLocalTime();
        var now = DateTime.Now;
        remainingTime = now < expiry ? expiry - now : TimeSpan.Zero;
        showSessionTimer = remainingTime.Value.TotalMinutes < 5;

        await InvokeAsync(StateHasChanged);
    }

    // ════════════════════════════════════════
    // DROPDOWN / MENU TOGGLE UI
    // ════════════════════════════════════════
    private void ToggleMenu(string type)
    {
        showLevelMenu = type == "level" ? !showLevelMenu : false;
        showNamHocMenu = type == "namhoc" ? !showNamHocMenu : false;
        showHocKyMenu = type == "hocky" ? !showHocKyMenu : false;
        showModuleMenu = type == "module" ? !showModuleMenu : false;
        StateHasChanged();
    }

    private void CloseAllDropdowns()
    {
        showLevelMenu = false;
        showNamHocMenu = false;
        showHocKyMenu = false;
        showModuleMenu = false;
        StateHasChanged();
    }

    private void ToggleMobileMenu()
    {
        _isMobileMenuOpen = !_isMobileMenuOpen;
        if (!_isMobileMenuOpen) expandedMenuTitle = null;
    }

    private void CloseMobileMenu()
    {
        _isMobileMenuOpen = false;
        expandedMenuTitle = null;
    }

    private void ToggleSubMenu(string title, bool hasSub, string link)
    {
        if (!hasSub)
        {
            NavManager.NavigateTo(link);
            CloseMobileMenu();
            return;
        }
        expandedMenuTitle = expandedMenuTitle == title ? null : title;
    }

    private void HandleLocationChanged(object? sender, LocationChangedEventArgs e)
    {
        if (_isMobileMenuOpen)
        {
            _isMobileMenuOpen = false;
            expandedMenuTitle = null;
            StateHasChanged();
        }
    }

    // ════════════════════════════════════════
    // HELPERS
    // ════════════════════════════════════════
    private static string GetLevelDisplayName(string cap) => cap switch
    {
        "02" => "Cấp Tiểu học",
        "03" => "Cấp THCS",
        "04" => "Cấp THPT",
        _ => "Không xác định"
    };

    public class LevelOption
    {
        public string Value { get; set; } = string.Empty;
        public string Text { get; set; } = string.Empty;
    }

    public class MenuItem
